import { artifacts } from "hardhat";
import * as fs from "fs";
import * as path from "path";

/** Writes typed ABI modules for the web app and the agent SDK. */
export async function exportAbi() {
  const arena = await artifacts.readArtifact("BountyArena");
  const usdc = await artifacts.readArtifact("MockUSDC");
  const store = await artifacts.readArtifact("ArenaTextStore");
  const body =
    "// Generated by contracts/scripts/export-abi.ts. Do not edit by hand.\n" +
    `export const arenaAbi = ${JSON.stringify(arena.abi, null, 2)} as const;\n\n` +
    `export const erc20Abi = ${JSON.stringify(usdc.abi, null, 2)} as const;\n\n` +
    `export const textStoreAbi = ${JSON.stringify(store.abi, null, 2)} as const;\n`;
  const targets = [
    path.join(__dirname, "../../web/src/lib/abi.ts"),
    path.join(__dirname, "../../agent-sdk/src/abi.ts"),
    path.join(__dirname, "../../verifier/src/abi.ts"),
    path.join(__dirname, "../../shared/src/abi.ts"),
  ];
  for (const t of targets) {
    fs.mkdirSync(path.dirname(t), { recursive: true });
    fs.writeFileSync(t, body);
  }
  console.log("ABI written to web, agent-sdk, verifier and shared");
}

if (require.main === module) {
  exportAbi().catch((e) => {
    console.error(e);
    process.exit(1);
  });
}
